INSERT INTO `document_files` VALUES (79, 337, '0_播出媒资存储升级函_20250513T085238093Z.jpg', '播出媒资存储升级函\\0_播出媒资存储升级函_20250513T085238093Z.jpg', 'image/jpeg', 69801, 0, 'YourHAL Wallet address\nhal1kj9f5le0lspxt8rcyc6vnn9yyfk9aqm5fd9kpq\nProvideyour e-mail address and name\nE-Mail address\nFirst name (as it appears in your passport)\nPlease use Latin characters,forexample,ifyournameis刘用（iu\nXiang)please enter only Xiang.\nAlso,omit any accents in your name,so please enter Jurgen as\nSubmit', 'completed', '2025-05-13 08:52:38', '2025-05-13 08:53:39');
INSERT INTO `document_files` VALUES (86, 348, '0_制播运维合同第一包-索贝_20250622T045927790Z.pdf', '制播运维合同第一包-索贝\\0_制播运维合同第一包-索贝_20250622T045927790Z.pdf', 'application/pdf', 6313135, 0, '安徽广播电视台移动传播平台后端内容生产和管理系统\n采购合同\n（第1包：生产区业务及功能增强和双向供稿平台系统）\n财政编号：_2019HACZ3738\n项目编号：RWHF2019-1371\n合同编号：CG-KJC-2019-0071\n电话：\n0551-65993602\n买方：安徽广播电视台\n电话：\n010-58985788\n卖方：北京中科大洋信息技术有限公司\n电话：\n0551 66223862\n见证方：安徽省政府采购中心\n买方通过安徽省政府采购中心组织的公开招标式采购活动，经评标委员会的\n评审，决定将本项目采购合同授予卖方。为进一步明确双方的责任，确保合同的\n顺利履行，根据《中华人民共和国政府采购法》、《中华人民共和国合同法》及\n有关法律规定，遵循平等、白愿、公平和诚实信用的原则，买卖双方协商一致同\n意按如下条款签订本合同：\n一、服务名称及内容\n具体见附件2《安徽广播电视台移动传播平台后端内容生产和管理系统采购\n（第1包：生产区业务及功能增强和双向供稿平台系统）货物清单》。\n二、组成合同的文件\n组成本合同的文件包括：\n（1）采购文件及答疑、更正公告；\n（2）采购文件标准文本中的“合同条款”：\n\n(3）中标或成交公告；\n（4）卖方提交的投标文件及书面承诺函；\n（5）双方另行签订的补充协议。\n三、合同金额\n本合同的总金额为￥1，670,000.00（人民币大写：壹佰陆拾柒万元整）。\n四、服务期限\n卖方应与安徽广播电视台移动传播平台后端内容生产和管理系统项目--第\n2包：归档区和暂存区系统、移动传播平台安全测试测评项日和移动传播平台前\n端系统项目中标供应商协同配合，并于合同签订之日起90日历日内完成合同规\n定的服务内容，由买方进行验收\n五、验收要求\n（一）质量标准\n卖方保证提供的服务质量应符合中华人民共和国相关标准及相应的技术规\n范、本次采购相关文件中的全部相关要求及卖方相关服务标准及相应的技术规范\n中之较高者。\n（二）验收组织\n买方负责组织验收工作，政府向社会公众提供的公共服务项目，验收时须邀\n请服务对象参与并出具意见，验收结果于验收结束之日起5个工作日内向社会公\n告。\n（三）验收程序\n1、成立验收小组，验收人员应由买方代表和技术专家组成。\n2、验收前要编制验收表格。\n3、验收时双方要按照验收表格逐项验收。\n\n4、验收方出具验收报告。\n六、付款方式\n1、合同生效后30个日历日内，买方支付给卖方65%合同款；\n2、项目验收合格后，买方支付35%合同款；\n3、每次付款前，卖方须提供经买方认可、等额、带抵扣联的增值税专用发\n票：否则，买方有权拒绝付款并不构成违约。\n七、售后服务\n（一）卖方对合同服务的质量保修期为验收证书签署之日起36个月，重要\n硬件设备提供百验收合格之日起3年原厂全免费质保的服务（包括3年部件、3\n年人工、3年现场）。\n验结果，发现服务的质量或性能与政府采购合同不符；或者在质量保证期内，证\n实服务是存在缺陷（包括潜在的缺陷等），买方应尽快以书面形式通知卖方。卖\n方在收到通知后7个日历日内免费维修或更换有缺陷的部分。\n（三）如卖方在收到通知后在政府采购合同规定时间内，没有弥补缺陷，买\n方可采取必要的补救措施，但由此引发的风险和费用将由卖方承担。\n八、履约保证金\n本项日履约保证金为￥83，500.00（人民币大写：捌万叁任伍值元整），收\n受人为安徽合肥公共资源交易中心，期限为验收合格后3年。如卖方未能\n按期履行合同，买方可从履约保证金中获得经济上的赔偿。\n九、违约责任\n（一）卖方服务期限超过合同约定服务期限。如果卖方由于自身的原因未能\n按期履行完合同，买方可从履约保证金中获得经济上的赔偿。其标准为按每延期\n\n一周收取合同金额的0.5%，但误期赔偿费总额不得超过履约保证金总额。\n周按7天计算，不足7天按周计算。在此情况下，卖方不得要求买方退还其履\n约保证金。\n（二）卖方服务期限内未能履约。卖方在履行合同过程中，如果遇到不能按\n时履约情况，应及时以书面形式将不能按期履约的理由、延误的时间通知买方。\n买方在收到卖方通知后，有权决定是否延长合同的履行时间或终止合同。如买方\n终止合同，卖方不得要求买方返还履约保证金：如买方同意延长合同的履行时间，\n卖方必须在买方规定的时间内提供符合质量标准的服务，由此造成的误期赔偿费\n按照前款约定执行。如卖方在买方规定的时间内未能提供符合质量标准的服务，\n买方有权终止合同，没收履约保证金，提请政府采购监管部门将卖方列入不良行\n为记录名单，在一至三年内禁止参加政府采购活动\n（三）卖方履约不符合约定的质量标准，卖方必须重新提供符合质量标准的\n服务，由此造成的误期赔偿费按照前款约定执行。如卖方在买方规定的时间内未\n能提供符合质量标准的服务，买方有权终止合同，没收履约保证金，提请政府采\n购蓝管部门将卖方列入不良行为记录名单，在一至三年内禁止参加政府采购活\n动。\n（四）卖方将合同转包、擅白变更、中止或者终止合同的，买方有权终止合\n同，并将提请政府采购蓝管部门对卖方进行采购金额千分之五的罚款，列入不良\n行为记录名单，在一至三年内禁止参加政府采购活动。\n（五）买方未能按时组织验收，由财政部门责令限期改正，给予警告，对直\n接负责的主管人员和其他直接责任人员，由其行政主管部门给予处分，并予通报，\n（六）买方违反合同规定拒绝接收服务的，应当承担由此造成的损失。\n（七）验收合格后，买方未能按时提请付款，中财政部门责令限期改正，给\n了警告。\n（八）买方擅自变更、中止或者终止合同，由财政部门责令限期改正，给予\n警告，对直接负责的主管人员和其他直接责任人员，由其行政主管部门给予处分，\n并予通报。\n十、合同签订地点\n\n本合同在安徽省合肥市蜀山区\n签订。\n十一、合同的终止\n（一）本合同因下列原因而终止：\n1、本合同正常履行完毕；\n2、合同双方协议终止本合同的履行：\n3、不可抗力事件导致本合同无法履行或履行不必要：\n播\n4、符合本合同约定的其他终止合同的条款。\n（二）对本合同终止有过错的一方应赔偿另一方因合同终止而受到的损失。\n对合同终止双方均无过错的，则各自承担所受到的损失。\n十二、其他\n（一）买卖双方必须严格按照采购文件、投标文件及有关承诺签订采购合同，\n不得擅自变更。合同执行期内，买卖双方均不得随意变更或解除合同。\n（二）本合同执行期问，如遇不可抗力，致使合同无法履行时，买卖双方应\n按有关法律规定及时协商处理。\n（三）合同未尽事宜：买卖双方另行签订补充协议，补充协议是合同的组成\n部分。\n（四）本合同如发生纠纷，买卖双方应当及时协商解决，协商不成时，按以\n72\n下第（②）项方式处理：①根据《中华人民共和国仲裁法》的规定向\n申\n请仲裁。②向_安徽省合肥市蜀山区_人民法院起诉。\n本合同一式陆份，白买卖双方法定代表人或委托代理人和见证方签字加盖单\n位公章后生效。\n买\n安徽广播电视台\n卖\n方：\n北京中科大洋\n5：\n信息\n民信店\n技术有限公司式\nLTL\n中\n单位盖章：\n凸\n法定代表人或委托专用章\n法定代表人或委托代理人：\n日\n期：\n日\n期：\n\n见证方：安徽省政府采购中心\n单位盖章：\n徽\n安\n法定代表人或委托代理\n合同见证章\n日期：\n\n合同附件：\n承诺函\n为维护招投标工作的严肃性，甲乙双方郑重声明并承诺如下：\n一、双方已明确知晓《中华人民共和国政府采购法》《政府采购货物和服务\n定：\n（一）《中华人民共和国政府采购法》第四十六条：采购人与中标、成交供\n应商应当在中标、成交通知书发出之日起三十日内，按照采购文件确定的事项签\n订政府采购合同。中标、成交通知书对采购人和中标、成交供应商均具有法律效\n力。中标、成交通知书发出后，采购人改变中标、成交结果的，或者中标、成交\n供应商放弃中标、成交项目的，应当依法承担法律责任。\n（二）《政府采购货物和服务招标投标管理办法》第七十一条：采购人应当\n白中标通知书发出之日起30日内，按照招标文件和中标人投标文件的规定，与\n中标人签订书面合同。所签订的合同不得对招标文件确定的事项和中标人投标文\n件作实质性修改。采购人不得向中标人提出任何不合理的要求作为签订合同的条\n件。\n（三）本项目采购公告和采购文件关于签订书面合同的相关约定（详见本项\n目采购公告和采购文件）。\n（四）采购人应在合同签订后2个工作日内进行合同公告。\n二、双方承诺严格按照上述规定签订安微广播电视台移动传播平台后端内容生\n产和管理系统采购的书面合同。\n中方：\n乙方：\n公\n法定付\n法定代表\n（签字\n（签字）\n安\n时间：\n年\n月\n19.11.\n时间：\n年\n月\n\n附件2：《安徽广播电视台移动传播平台后端内容生产和管理系统采\n购（第1包：生产区业务及功能增强和双向供稿平台系统）货物清单》\n卖方须根据招标文件要求，提供满足本项目功能、性能要求的一切货物，以\