INSERT INTO `document_files` VALUES (95, 339, '0_索贝支持文体直播马拉松报告_20250622T093853988Z.pdf', '索贝支持文体直播马拉松报告\\0_索贝支持文体直播马拉松报告_20250622T093853988Z.pdf', 'application/pdf', 3359361, 0, '合同编号：CG-JSZX-2021-0036\n政府采购合同\n(货物类)\n项目名称：安徽广播电视台技术系统媒体融合改造及设备更\n新第6包新媒体直播推流一体化设备采购\n项目编号：2021BFAHZ02179\n甲方（采购人）：安徽广播电视台\n乙方（中标人）：南京坤源博文数字科技有限公司\n签订地：安徽省合肥市\n签订日期：\n年\n月\n日\n第1页共9页\n\n合同编号：CG-JSZX-2021-0036\n第一部分合同书\n安徽广播电视台（以下简称：甲方）通过安徽省政采项目管理咨询有限公司组织的公开\n招标方式采购活动，经评标委员会评定，南京坤源博文数字科技有限公司（以下简称：乙方）\n为本项目中标人，现按照采购文件确定的事项签订本合同。\n根据《中华人民共和国民法典》《中华人民共和国政府采购法》等相关法律法规之规定，\n按照平等、自愿、公平和诚实信用的原则，经甲方和乙方协商一致，约定以下合同条款，以\n兹共同遵守、全面履行。\n1.1合同组成部分\n下列文件为本合同的组成部分，并构成一个整体，需综合解释、相互补充。如果下列文\n件内容出现不一致的情形，那么在保证按照采购文件确定的事项前提下，组成本合同的多个\n文件的优先适用顺序如下：\n1.1.1本合同及其补充合同、变更协议；\n1.1.2中标通知书；\n1.1.3投标文件（含澄清或者说明文件）；\n1.1.4招标文件（含澄清或者修改文件）；\n1.1.5其他相关采购文件。\n1.2货物\n序号\n货物名称\n规格型号\n单位\n数量\n生产厂商\n新媒体直播推流一\n南京纳加软件股份\nNSCaster558\n台\n1\n4\n体化设备\n有限公司\n便携式直播导播设\n亿播网视科技有限\nUcast-R8\n台\n6\n2\n备\n公司\nTYPE-C转HDMI连\n深圳市绿联科技股\n转接线1\n根\n6\n接线（1.5米）\n份有限公司\nHDMI 转SDI高清\n深圳市绿联科技股\n转换器1\n根\n4\n12\n转换器\n份有限公司\nSDI转HDMI高清\n深圳市绿联科技股\n5\n转换器2\n根\n12\n转换器\n份有限公司\n南京坤源博文数字\n通用IP流解码器\nD300\n台\n6\n6\n科技有限公司\n南京纳加软件股份\n4G/5G聚合路由器\n花火\n台\n7\n4\n有限公司\n1.3价款\n本合同总价为：￥586834.00（大写：人民币伍拾捌万陆任捌佰叁拾肆元整）。\n分项价格：\n第2页共9页\n\n合同编号：CG-JSZX-2021-0036\n序号\n分项名称\n分项价格（元）\n1\n新媒体直播推流一体化设备\n480000.00\n2\n便携式直播导播设备\n60000.00\n3\n转接线1\n6. 00\n4\n转换器1\n12.00\n5\n转换器2\n12.00\n6\n通用IP流解码器\n46800.00\n7\n4G/5G聚合路由器\n4.00\n1.4付款方式和发票开具方式\n1.4.1付款方式：合同签订后，支付80%合同款；项目验收合格后支付15%合同款；质\n保期满后支付剩余5%合同款；\n1.4.2发票开具方式：13%税率增值税专用发票。\n1.5货物交付期限、地点和方式\n1.5.1交付期限：合同签订后60日历天内完成交货及安装调试；\n1.5.2交付地点：安徽广播电视台（合肥市蜀山区龙图路666号）；\n1.5.3交付方式：乙方负责货物运输至甲方指定地点，安装完成后交付甲方；\n1.5.4质保期：验收合格之日起新媒体直播推流一体化设备、便携式直播导播设备、通\n用IP流解码器、4G/5G聚合路由器设备5年原厂质保，其它设备3年原厂质保。\n1.6违约责任\n1.6.1除不可抗力外，如果乙方没有按照本合同约定的期限、地点和方式交付货物，那\n么甲方可要求乙方支付违约金，违约金按每迟延交付货物一日的应交付而未交付货物价格的\n0.5%计算，最高限额为本合同总价的30%；迟延交付货物的违约金计算数额达到前述最高限\n额之日起，甲方有权在要求乙方支付违约金的同时，书面通知乙方解除本合同；\n1.6.2除不可抗力外，如果甲方没有按照本合同约定的付款方式付款，那么乙方可要求\n甲方支付违约金，违约金按每迟延付款一日的应付而未付款的0.5%计算，最高限额为本合\n同总价的30%；迟延付款的违约金计算数额达到前述最高限额之日起，乙方有权在要求甲方\n支付违约金的同时，书面通知甲方解除本合同；\n1.6.3除不可抗力外，任何一方未能履行本合同约定的其他主要义务，经催告后在合理\n期限内仍未履行的，或者任何一方有其他违约行为致使不能实现合同目的的，或者任何一方\n相的方法来影响对方当事人在合同签订、履行过程中的行为）的，对方当事人可以书面通知\n违约方解除本合同；\n第3页共9页\n\n合同编号：CG-JSZX-2021-0036\n1.6.4任何一方按照前述约定要求违约方支付违约金的同时，仍有权要求违约方继续履\n行合同、采取补救措施，并有权按照已方实际损失情况要求违约方赔偿损失；任何一方按照\n前述约定要求解除本合同的同时，仍有权要求违约方支付违约金和按照已方实际损失情况要\n求违约方赔偿损失；且守约方行使的任何权利救济方式均不视为其放弃了其他法定或者约定\n的权利救济方式；\n1.6.5除前述约定外，除不可抗力外，任何一方未能履行本合同约定的义务，对方当事\n人均有权要求继续履行、采取补救措施或者赔偿损失等，且对方当事人行使的任何权利救济\n方式均不视为其放弃了其他法定或者约定的权利救济方式；\n1.6.6如果出现政府采购监督管理部门在处理投诉事项期间，书面通知甲方暂停采购活\n动的情形，或者询问或质疑事项可能影响中标结果的，导致甲方中止履行合同的情形，均不\n视为甲方违约。\n1.7合同争议的解决\n本合同履行过程中发生的任何争议，双方当事人均可通过和解或者调解解决；不愿和解、\n调解或者和解、调解不成的，可以选择下列第1.7.2种方式解决：\n1.7.1将争议提交\n仲裁委员会依申请仲裁时其现行有效的仲裁规则裁决；\n1.7.2向里方所在地有管辖权的人民法院起诉。\n1.8合同生效\n本合同自双方当事人盖章时生效。\n播电\n（单位盖章）\n乙方：\n（单位盖章）\n甲\n方：\n南\n安\n哈专用章\n法定代表人\n法定代表人\n或授权代表（签字）：\n或授权代表（签字）：\n时间：\n时间：202丨年1月1日\n年\n月\n日\n省\n安\n合国见证章\n4页共9页\n202110.20\n\n合同编号：CG-JSZX-2021-0036\n第二部分合同一般条款\n2.1定义\n本合同中的下列词语应按以下内容进行解释：\n的附件、附录和构成合同的其他文件。\n2.1.2“合同价”系指根据合同约定，中标人在完全履行合同义务后，采购人应支付给\n中标人的价格。\n2.1.3“货物”系指中标人根据合同约定应向采购人交付的一切各种形态和种类的物品，\n包括原材料、燃料、设备、机械、仪表、备件、计算机软件、产品等，并包括工具、手册等\n其他相关资料。\n2.1.4“甲方”系指与中标人签署合同的采购人；采购人委托采购代理机构代表其与乙\n方签订合同的，采购人的授权委托书作为合同附件。\n他组织组成一个联合体，以一个供应商的身份共同参加政府采购的，联合体各方均应为乙方\n或者与乙方相同地位的合同当事人，并就合同约定的事项对甲方承担连带责任。\n2.2技术规范\n及其技术规范偏差表（如果被甲方接受的话）相一致；如果采购文件中没有技术规范的相应说\n明，那么应以国家有关部门最新颁布的相应标准和规范为准。\n专\n2.3知识产权\n2.3.1乙方应保证甲方在使用该货物或其任何一部分时不受任何第三方提出的侵犯其\n著作权、商标权、专利权等知识产权方面的起诉；如果任何第三方提出侵权指控，那么乙方\n须与该第三方交涉并承担由此发生的一切责任、费用和赔偿；\n2.3.2具有知识产权的计算机软件等货物的知识产权归属，详见合同专用条款。\n2.4包装和装运\n2.4.1除合同专用条款另有约定外，乙方交付的全部货物，均应采用本行业通用的方式\n进行包装，没有通用方式的，应当采取足以保护货物的包装方式，且该包装应符合国家有关\n包装的法律、法规的规定。如有必要，包装应适用于远距离运输、防潮、防震、防锈和防粗\n暴装卸，确保货物安全无损地运抵现场。由于包装不善所引起的货物锈蚀、损坏和损失等一\n切风险均由乙方承担。\n2.4.2装运货物的要求和通知，详见合同专用条款。\n公\n2.5履约检查和问题反馈\n2.5.1甲方有权在其认为必要时，对乙方是否能够按照合同约定交付货物进行履约检\n第5页共9页\n\n合同编号：CG-JSZX-2021-0036\n查，以确保乙方所交付的货物能够依约满足甲方项目需求，但不得因履约检查妨碍乙方的正\n常工作，乙方应予积极配合；\n2.5.2合同履行期间，甲方有权将履行过程中出现的问题反馈给乙方，双方当事人应以\n书面形式约定需要完善和改进的内容。\n2.6结算方式和付款条件\n详见合同专用条款。\n2.7技术资料和保密义务\n2.7.1乙方有权依据合同约定和项目需要，向甲方了解有关情况，调阅有关资料等，甲\n方应予积极配合;\n2.7.2乙方有义务妥善保管和保护由甲方提供的前款信息和资料等；\n2.7.3除非依照法律规定或者对方当事人的书面同意，任何一方均应保证不向任何第三\n方提供或披露有关合同的或者履行合同过程中知悉的对方当事人任何未公开的信息和资料，\n包括但不限于技术情报、技术资料、商业秘密和商业信息等，并采取一切合理和必要措施和\n方式防止任何第三方接触到对方当事人的上述保密信息和资料。\n2.8质量保证\n2.8.1乙方应建立和完善履行合同的内部质量保证体系，并提供相关内部规章制度给甲\n方，以便甲方进行监督检查；\n2.8.2乙方应保证履行合同的人员数量和素质、软件和硬件设备的配置、场地、环境和\n设施等满足全面履行合同的要求，并应接受甲方的监督检查。\n2.9 货物的风险负担\n货物或者在途货物或者交付给第一承运人后的货物毁损、灭失的风险负担详见合同专用\n条款。\n2.10延迟交货\n在合同履行过程中，如果乙方遇到不能按时交付货物的情况，应及时以书面形式将不能\n按时交付货物的理由、预期延误时间通知甲方；甲方收到乙方通知后，认为其理由正当的，\n可以书面形式酌情同意乙方可以延长交货的具体时间。\n2.11合同变更\n2.11.1双方当事人协商一致，可以签订书面补充合同的形式变更合同，但不得违背采\n购文件确定的事项；\n2.11.2合同继续履行将损害国家利益和社会公共利益的，双方当事人应当以书面形式\n变更合同。有过错的一方应当承担赔偿责任，双方当事人都有过错的，各自承担相应的责任。\n2.12合同转让和分包\n合同的权利义务依法不得转让，但经甲方同意，乙方可以依法采取分包方式履行合同，\n即：依法可以将合同项下的部分非主体、非关键性工作分包给他人完成，接受分包的人应当\n第6页共9页\n\n合同编号：CG-JSZX-2021-0036\n具备相应的资格条件，并不得再次分包，且乙方应就分包项目向甲方负责，并与分包供应商\n就分包项目向甲方承担连带责任。\n2.13不可抗力\n2.13.1如果任何一方遭遇法律规定的不可抗力，致使合同履行受阻时，履行合同的期\n限应予延长，延长的期限应相当于不可抗力所影响的时间；\n2.13.2因不可抗力致使不能实现合同目的的，当事人可以解除合同；\n2.13.3因不可抗力致使合同有变更必要的，双方当事人应在合同专用条款约定时间内\n以书面形式变更合同；\n2.13.4受不可抗力影响的一方在不可抗力发生后，应在合同专用条款约定时间内以书\n面形式通知对方当事人，并在合同专用条款约定时间内，将有关部门出具的证明文件送达对\n方当事人。\n2.14税费\n与合同有关的一切税费，均按照中华人民共和国法律的相关规定缴纳。\n2.15乙方破产\n如果乙方破产导致合同无法履行时，甲方可以书面形式通知乙方终止合同且不给予乙方\n任何补偿和赔偿，但合同的终止不损害或不影响甲方已经采取或将要采取的任何要求乙方支\n付违约金、赔偿损失等的行动或补救措施的权利。\n2.16合同中止、终止\n2.16.1双方当事人不得擅自中止或者终止合同；\n2.16.2合同继续履行将损害国家利益和社会公共利益的，双方当事人应当中止或者终\n止合同。有过错的一方应当承担赔偿责任，双方当事人都有过错的，各自承担相应的责任。\n2.17检验和验收\n3\n2.17.1货物交付前，乙方应对货物的质量、数量等方面进行详细、全面的检验，并向\n甲方出具证明货物符合合同约定的文件：货物交付时，乙方在合同专用条款约定时间内组织\n验收，并可依法邀请相关方参加，验收应出具验收书。\n2.17.2合同期满或者履行完毕后，甲方有权组织（包括依法邀请国家认可的质量检测\n机构参加）对乙方履约的验收，即：按照合同约定的技术、服务、安全标准，组织对每一项\n技术、服务、安全标准的履约情况的验收，并出具验收书。\n2.17.3检验和验收标准、程序等具体内容以及前述验收书的效力详见合同专用条款。\n2.18计量单位\n除技术规范中另有规定外，合同的计量单位均使用国家法定计量单位。\n2.19合同使用的文字和适用的法律\n2.19.1合同使用汉语书就、变更和解释；\n2.19.2合同适用中华人民共和国法律。\n第7页共9页\n\n合同编号：CG-JSZX-2021-0036\n2.20履约保证金\n2.20.1采购文件要求乙方提交履约保证金的，乙方应按合同专用条款约定的方式，以\n支票、汇票、本票或者金融机构、担保机构出具的保函等非现金形式，提交不超过合同价\n10%的履约保证金；\n完全有效，前述约定期间届满或者货物质量保证期届满之日起22个工作日内，甲方应将履\n约保证金退还乙方；\n2.20.3如果乙方不履行合同，履约保证金不予退还；如果乙方未能按合同约定全面履\n行义务，那么甲方有权从履约保证金中取得补偿或赔偿，同时不影响甲方要求乙方承担合同\n约定的超过履约保证金的违约责任的权利。\n2.21合同份数\n合同份数按合同专用条款规定，每份均具有同等法律效力。\n桃\n1ir\n正\n第8页共9页\n\n合同编号：CG-JSZX-2021-0036\n第三部分\n合同专用条款\n本部分是对前两部分的补充和修改，如果前两部分和本部分的约定不一致，应以本部分\n的约定为准。本部分的条款号应与前两部分的条款号保持对应；与前两部分无对应关系的内\n容可另行编制条款号。\n条款号\n约定内容\n2.3.2\n除法律另有规定或者当事人另有约定的以外，本合同货物的知识产权不属于\n甲方。\n2.4.1\n无\n2.4.2\n甲方收货联系人：王洁（电话：0551-65993603）。\n2.6\n付款方式：合同签订后，支付80%合同款；项目验收合格后支付15%合同款；\n质保期满后支付剩余5%合同款。\n付款条件：甲方付款前，乙方须开具13%税率的增值税专用发票。\n2.9\n货物或者在途货物或者交付给第一承运人后的货物毁损、灭失的风险由乙方\n承担。\n2.13.3\n因不可抗力致使合同有变更必要的，双方当事人应在不可抗力发生后60日内\n以书面形式变更合同。\n2.13.4\n受不可抗力影响的一方在不可抗力发生后，应在30日内以书面形式通知对方\n当事人，并在60日内，将有关部门出具的证明文件送达对方当事人。\n2.17.1\n无\n2.17.3\n所有设备安装调试完成后进入试运行，正常试运行6个月后，由乙方提出验\n收申请，甲方在收到验收申请30日内组织验收，并出具验收报告。\n如国家规定或合同约定须由第三方进行验收的，所发生的费用由乙方承担；\n货物规格或指标应符合相关国家、行业标准，并满足合同、投标文件、招标\n文件的约定或要求。\n2.20.1\n无\n2.20.2\n无\n2.21\n本合同一式陆份，甲方执肆份，乙方执贰份。\n第9页共9页', 'completed', '2025-06-22 09:38:53', '2025-06-22 09:40:35');
INSERT INTO `document_files` VALUES (98, 338, '0_索贝支持《直播安徽》报告_20250622T101049900Z.pdf', '索贝支持《直播安徽》报告\\0_索贝支持《直播安徽》报告_20250622T101049900Z.pdf', 'application/pdf', 2127567, 0, '合同编号：CG-JSZX-2022-031\n安徽广播电视台融媒体新闻演播系统改造项目\n第2包：新闻直播回传系统采购合同\n财政编号：FS34000120224896号\n项目编号：ZF2022-05-0427\n合同编号：CG-JSZX-2022-031\n买方：安徽广播电视台\n电话：0551-65993602\n卖方：南京坤源博文数字科技有限公司\n电话：15151868797\n评审，决定将本项目采购合同授予卖方。为进一步明确双方的责任，确保合同的顺利履行，\n根据《中华人民共和国政府采购法》、《中华人民共和国民法典》及有关法律规定，遵循平\n等、自愿、公平和诚实信用的原则，买卖双方协商一致同意按如下条款签订本合同。\n一、货物的名称、规格型号、数量和价格\n单位：元\n产品名称\n品牌规格型号\n单位\n数量\n单价(元)\n小计 （元）\n生产厂商\n直播移动编码\nLive U\n台\n6\n135000\n810000\nLive U. Ltd\n器（单兵背包）\nLU600\n解码控制软件\nLive U\n及配套接收解\n台\n3\n60500\n181500\nLive U. Ltd\nLU2000\n码服务器\n坤源博文\n南京坤源博文数\n高清光端机\n对\n2\n13000\n26000\nKVW-250\n字科技有限公司\n迈拓维矩\nKVM\n台\n1\n11000\n11000\n迈拓维矩\nMT-17308HL\n台\n5G随身WIfi\n华为E6878-370\n4\n5500\n22000\n华为\n落地式笔记本\n派凡 落地款\n台\n400\n400\n派凡\n1 \n支架\n移动式落地升\n易游\n台\n1\n1300\n1300\n易游\n降桌\nA1\nSDI一进二出分\n迈拓维矩\n个\n6\n1400\n8400\n迈拓维矩\n配器\nMT-SD102\nSDI转光信号延\n坤源博文\n南京坤源博文数\n对\n4\n6500\n26000\n长器\nKJ-100\n字科技有限公司\n第1页共5页\n\n合同编号：CG-JSZX-2022-031\n合计\nY1086600. 00\n合同总金额（大写）：壹佰零捌万陆仟陆佰元整\n备注：上述产品报价含货物的供货、包装运输（包括卸车及就位至招标人指定的安装地点）、安\n装、调试、验收、技术服务、培训、售后服务等所有内容。\n二、组成合同的文件\n组成本合同的文件包括：\n（1）采购文件及答疑、更正公告；\n（2）采购文件标准文本中的“合同条款”；\n(3）中标或成交公告；\n（4）卖方提交的投标文件及书面承诺函；\n（5）双方另行签订的补充协议。\n三、合同金额\n本合同的总金额为￥1,086，600.00元（人民币大写：壹佰零捌万陆任陆佰元整）。\n四、供货期限\n合同签订生效之日起60日内卖方完成设备供货，合同签订生效之日起90日内卖方完\n成安装调试。货物运输至买方指定地点到货物验收合格前，卖方_负责对货物承担安保义务。\n五、验收要求\n（一）质量标准\n卖方保证提供的货物符合中华人民共和国国家及行业的安全质量标准、环保标准中之较\n高者；若货物来源于中华人民共和国境外，还要同时符合货物来源国的官方、行业及生产厂\n商的安全质量标准、环保标准中之较高者。上述标准为已发布的且在货物交付时有效的最新\n版本的标准；当货物来源于中华人民共和国境外时，产品必须附有原产地证明、中华人民共\n和国商检机构的检验证明、合法进货渠道证明及海关完税证明，此外，有关技术资料中须附\n口\n有全文翻译的中文文本。\n（二）验收组织\n买方负责组织验收工作，大型或者复杂的政府采购项目，必须邀请国家认可的质量检测\n机构参加验收工作。\n（三）验收程序\n1、成立验收小组，验收人员应由买方代表和技术专家组成。\n2、验收前要编制验收表格。\n3、验收时双方要按照验收表格逐项验收。\n4、验收方出具验收报告。\n第2页共5页\n\n合同编号：CG-JSZX-2022-031\n5、复杂设备的验收还要包括出厂检验、到货检验、安装和调试、最终验收、培训等伴\n随服务的验收。\n六、付款方式\n本项目付款方式如下：\n合同签订后买方支付合同价款的40%作为预付款，待所有货物供货安装调试完毕后付至\n合同价款的95%，经买方验收合格后一次性付清剩余合同价款。每次付款前卖方须开具对应\n金额的符合国家有关规定的增值税专用发票。\n七、售后服务\n（一）卖方对合同货物的质量保修期为验收证书签署之日起36个月。\n（二）卖方在合同货物的质量保修期内，免费为买方提供合同货物的技术指导和维修服\n务服务的时间是：每周5天40小时（工作时间）。\n（三）卖方保证在合同货物出现故障和缺陷时，或接到买方提出的技术服务要求后_24\n小时内予以答复，如买方有要求或必要时，卖方应在接到买方通知后5日内派员至买方免\n费维修和提供现场指导。\n用\n（四）如卖方在接到买方维修通知后7日仍不能修复有关货物，卖方应提供与该货物\n同一型号的备用货物。\n（五）如卖方在接到买方提出的技术服务要求或维修通知后_72小时内没有响应、拒绝\n或没有派员到达买方提供技术服务、修理或退换货物，买方有权委托第三方对合同货物进行\n科\n维修或提供技术服务，因此产生的相关费用由卖方承担。\n（六）在合同货物保修期届满后，如果因合同货物硬件或软件的固有缺陷和瑕疵出现紧\n急故障和事故，卖方应在接到买方通知之后_15日内到达现场。\n转\n八、履约保证金\n本项目履约保证金为￥27165.00元（人民币大写：贰万柒任壹佰陆拾伍元整），收受\n11000\n人为安徽广播电视台，期限为项目验收合格后无息退还。如卖方未能按期履行合同，买\n方可从履约保证金中获得经济上的赔偿。\n九、违约责任\n（一）卖方供货期超过合同约定供货期限。如果卖方由于自身的原因未能按期履行完合\n同，买方可从履约保证金中获得经济上的赔偿。其标准为按每延期一周收取合同金额的1%，\n但误期赔偿费总额不得超过履约保证金总额。一周按7天计算，不足7天按一周计算。在\n此情况下，卖方不得要求买方退还其履约保证金。\n第3页共5页\n\n合同编号：CG-JSZX-2022-031\n（二）卖方供货期内未能交货。卖方在履行合同过程中，如果遇到不能按时交货情况，\n应及时以书面形式将不能按期履行合同的理由、延误的时间通知买方。买方在收到卖方通知\n后，如延期超过 70天，买方有权决定是否延长合同的履行时间或终止合同。如买方终止合\n同，卖方不得要求买方返还履约保证金；如买方同意延长合同的履行时间，卖方必须在买方\n规定的时间内提供符合质量标准的产品，由此造成的误期赔偿费按照前款约定执行。如卖方\n在买方规定的时间内未能提供符合质量标准的产品，买方有权终止合同，扣留履约保证金，\n动。\n（三）卖方交货不符合合同质量标准，卖方必须重新提供符合质量标准的产品，由此造\n成的误期赔偿费按照前款约定执行。如卖方在买方规定的时间内未能提供符合质量标准的产\n品，买方有权终止合同，扣留履约保证金，提请政府采购监管部门将卖方列入不良行为记录\n名单，在一至三年内禁止参加政府采购活动。\n（四）卖方将合同转包，提供假冒伪劣产品，擅自变更、中止或者终止合同的，买方有\n章\n权终止合同，并将提请政府采购监管部门对卖方进行采购金额千分之五的罚款，列入不良行\n为记录名单，在一至三年内禁止参加政府采购活动。\n（五）买方未能按时组织验收，由财政部门责令限期改正，给予警告，对直接负责的主\n管人员和其他直接责任人员，由其行政主管部门给予处分，并予通报。\n（六）买方违反合同规定拒绝接收货物的，应当承担由此造成的损失。\n（七）验收合格后，买方未能按时提请付款。由财政部门责令限期改正，给予警告。\n（八）买方擅自变更、中止或者终止合同，由财政部门责令限期改正，给予警告，对直\n月章\n接负责的主管人员和其他直接责任人员，由其行政主管部门给予处分，并予通报。\n819\n十、签约地点\n本合同在合肥市签订。\n十一、合同的终止\n（一）本合同因下列原因而终止：\n1、本合同正常履行完毕;\n2、合同双方协议终止本合同的履行；\n3、不可抗力事件导致本合同无法履行或履行不必要；\n4、符合本合同约定的其他终止合同的条款。\n第4页共5页\n\n合同编号：CG-JSZX-2022-031\n（二）对本合同终止有过错的一方应赔偿另一方因合同终止而受到的损失。对合同终止\n双方均无过错的，则各自承担所受到的损失。\n十二、其他\n（一）买卖双方必须严格按照采购文件、投标文件及有关承诺签订采购合同，不得擅自\n变更。合同执行期内，买卖双方均不得随意变更或解除合同。\n（二）本合同执行期间，如遇不可抗力，致使合同无法履行时，买卖双方应按有关法律\n规定及时协商处理。\n（三）合同未尽事宜，买卖双方另行签订补充协议，补充协议是合同组成部分。\n（四）本合同如发生纠纷，买卖双方应当及时协商解决，协商不成时，按以下第（①)\n项方式处理：①根据《中华人民共和国仲裁法》的规定向_合肥仲裁委员会申请仲裁。②向\n买方所在地起诉。\n本合同一式陆份，买方持贰份，卖方持贰份，见证方持壹份。本合同自买卖双方法定代\n表人或委托代理人签字加盖单位公章后生效。\n买方：\n安徽广播电视台\n卖方：南京坤源博文数字科技有限公司\n猫\n坤\n京\n视\n合同专用章\n单位盖章人\n单位盖章：\n合同专用章\n面\n法定代表人或委托代理人：\n法定代表人或委托代理人：\n日期：\n日期：2。.7.2\n第5页共5页', 'completed', '2025-06-22 10:10:49', '2025-06-22 10:22:11');
INSERT INTO `document_files` VALUES (101, 335, '0_文体戴本祠退休_20250622T103423134Z.pdf', '文体戴本祠退休\\0_文体戴本祠退休_20250622T103423134Z.pdf', 'application/pdf', 1896655, 0, NULL, 'pending', '2025-06-22 10:34:23', '2025-06-22 10:34:23');
INSERT INTO `document_files` VALUES (104, 334, '0_新闻制播系统升级采购_20250623T093416361Z.pdf', '新闻制播系统升级采购\\0_新闻制播系统升级采购_20250623T093416361Z.pdf', 'application/pdf', 1896655, 0, '县级融媒体中心省级技术平台三期：\n皖云省级技术平台全媒体媒资库建设项\n目一第4标段：重点历史媒资上载编目\n合同\n项目名称：县级融媒体中心省级技术平台三期：皖云省\n级技术平台全媒体媒资库建设项目-第4标段：重点历史媒资\n上载编目\n项目编号：2022BTWCZ00498\n委托方：_安徽皖云传媒科技股份有限公司\n（甲方）\n受托方：_成都索贝运维数码科技有限公司\n(乙方)\n签订时间：\n2022年8月\n签订地点：\n安徽省合肥市\n\n合同双方：\n委托方：安徽皖云传媒科技股份有限公司（以下简称“甲方”）\n受托方：成都索贝运维数码科技有限公司（以下简称“乙方”）\n依据《中华人民共和国民法典》规定，甲乙双方就皖云省级技术\n平台全媒体媒资库建设项目一第4标段：重点历史媒资上载编目事宜，\n经双方友好协商，签订本合同，以资共同遵守。甲乙双方在本合同项\nZL\n下所载各项条款表示完全同意和理解。\n第一条定义\n除非另有约定，本合同项下的相关词语、术语均以本条下列释译、\n表述为准。\n1.“本服务”指_第4标段：重点历史媒资上载编目。\n2.“合同总价款”：指申方支付乙方按照合同约定完成全部服务\n的总款项。\n3.“合同执行期”：指申乙双方在合同中约定，按总日历天数计\n算的有效完成合同任务的天数。\n4.“书面形式”：指合同书、信件和数据电文（包括电报、电传、\n传真、电子数据交换和电子邮件）等可以有形地表现所载内容的形式。\n5.“违约责任”：指合同一方不履行合同义务或履行合同义务不\n符合约定所应承担的责任。\n6.“索赔”：指在合同履行中，对于并非自己的过错，而是应由\n对方承担责任的情况造成的实际损失，向对方提出经济补偿和（或）\n工期顺延的要求。\n2\n\n7.“不可抗力”：指不能预见、不能避免并不能克服的客观情况。\n8.本合同中规定按天计算时间的，开始当天不计入，从次日开始\n计算。时限的最后一天是休息日或者其他法定节假日的，以节假日次\n日为时限的最后一大，但工日期除外。时限的最后一天的截止时间\n为当日24时。\n第二条项目标的技术内容、范围、形式和要求：\n总体要求：\nM\n1、所有任务须在合同生效后，乙方接到人员进场施工的书面通\n知之日起12个月以内完成服务。\n2、须在安徽广播电视台提供的本合同项目固定场地开展工作。\n3、使用安徽广播电视台提供的媒资上载、编目、审核工作站和\n软件进行相关工作。注：招标方只提供上载、编目、审核工作站，磁\n带等介质上载的放像设备由中标方自带（带型/文件格式包括但不限\n1\n于VO、BVU、SP、DVCpro、IMX、DVW、JVC Digital S、蓝光等）\n4、本合同内容为2500小时的3/4带型（V0、BVU等）磁带上\n载，服务单价95元/小时。8500小时的其他带型（SP、DVCPr0、IMX、\nDVW、JVCDigitalS、蓝光等）磁带上载，服务单价70元/小时；11000\n小时媒资编目，服务单价200元/小时。以上构成仅为预估量，最终\n以实际提供量为准。\n流程要求：\n1、乙方的工作流程包含预上载、上载、人工QC、编目、编目一\n审、编目二审（编目终审由招标方进行)等，乙方根据工效制定合理的\n3\n\n实施方案。\n2、磁带预上载流程须包含：磁带质量评估、断带修复、清理、转\n录等流程，具体流程依实际情况确定。\n质量要求：\n1、磁带上载须保证节目的完整，断带修复坚持图像损失最小化\n原则；\n2、乙方要协助甲方根据实际情况完善安徽广播电视台制定的各\n司\n节目类型编目细则；\n3、乙方提供专业编目人员遵照安徽广播电视台制定的编目细则，\n根据节目种类和具体需求进行编目。\n4、要求乙方对甲方的相关工作人员免费提供全流程培训（包括但\n不限于上载、编目、审核等）；\n5、甲方有权在本合同实施过程中对编目细则进行适当修改，乙\n方须配合执行；\n6、要求乙方安排资深专业人士对编目进行全面编目审核和数据\n回溯，甲方负责终审，乙方对不符合编目标准的资料重新编目，确保\n编目质量。\n人员要求：\n1、本合同项目负责人：受过系统的管理专业训练，具有地市级或\n地市级以上编目项目现场管理实施经验，且项目管理经验不低于2年、\n参与的项目人员数量不少于15人。项目负责人须定期参加甲方组织\n的相关会议，并及时向甲方汇报各节点数据统计结果。\n\n2、本合同项目其他人员：正式上岗的人员中，拥有2年以上相\n关工作经验的人员占总人数的比例应大于30%。正式上岗的人员必须\n具有大专以上学历。\n3、本合同项目人员构成：乙方的正式上岗成员需包含磁带质量评\n估、断带修复、老旧带型磁带上载、人工质检、编目、编目审核等专\n业人员。\n4、人员稳定要求：要求保持编目人员整体队伍稳定。中标后，在\n专\n本合同项目实施过程中，成员总流动比例不得超过30%。\n5、保密性要求：要求乙方所有工作人员保证招标人节目资料的安\n全，并签订保密协议，杜绝任何形式的节自资料外泄情况。\n第三条合同履行计划、进度、期限\n技术服务时间：自接到人员进场施工的书面通知之日起12个月\n以内完成服务。\n三\n第四条合同价款及支付方式\n1.该项目合同总价金额：人民币叁佰零叁万贰任伍佰元整\n（￥3032500元）\n2.付款前，由乙方于本合同生效后提出付款申请、出具等额发票，\n甲方收到发票后核对并根据发票金额在5个工作日内办理支付手续。\n3.乙方收款账户信息：\n户名：成都索贝运维数码科技有限公司\n开户行：中国光大银行股份有限公司成都光华支行\n账号：78270188000098175\n\n4.合同签订后付至合同总价的30%，人员到位后付至90%，经招\n标人验收合格后一次性付清余款。\n5.乙方须预先支付给甲方合同总价的5%的履约保证金，待项目验\n收1年后无售后质保问题的情况下归还。\n第五条项目验收\nM\n乙方按照约定的进度计划完成合同规定的服务内容并稳定执行\n月\n一段时间后，书面向甲方提出验收申请；甲方在乙方提出验收的7天\n内，组织验收专家组进行确认，确认达到项目功能要求后，甲方在《项\n目验收意见书》上签字确认后验收通过，或提出整改意见，由乙方完\n成后再验收通过。\n因乙方单方面原因导致延期交付或延期安装完成、延期完成验收，\n则每逾期一天按照2000元/日向甲方支付违约金；超过20日，甲方\n有权解除合同，并要求乙方按照合同总额的20%支付违约金。\n第六条甲乙双方的权利与义务\n1.甲方权利\n（1）甲方应按照合同及工作任务书的约定指派相应的人员组成\n项目组，并保证指派专门的人员负责执行合同条款中的各项工作；\n（2）在任何时候，甲方对乙方指定专业人员的主要工作表现不\n满意，可立即书面告知乙方，并可要求乙方更换人员。乙方需采取合\n理措施予以解决。\n（3）甲方拥有整个项目内所有输出物及过程文件的版权和使用\n\n（3）如果甲方未能按照合同约定，如约支付款项给乙方，乙方\n有权利停止提供上载和编目服务，或完成已付款项的服务额度。\n4.乙方义务\n（1）乙方应按照甲方及本合同要求，提供优质上载及编目服务，\n并在甲方指定的信息系统中完成合同约定生产任务。根据甲方工作需\n求、进度要求及实际情况制定详细的实施管理规范和实施计划，确保\n项目按时保质完成。\n（2）乙方在本合同项目实施过程中应服从甲方统一协调，对甲\n方的相关规章制度与规范予以遵照执行，并在各阶段根据招标方的需\n要交各种相关文档。主要包括（但不限于)本合同的项目实施计划、应\n急处理计划、项目管理方案、质量控制方案、人员组织机构和职责分\n工、项目实施阶段性报告、总结报告等项目文档，并确保各类文档统\n计数据的真实准确。\n（3）本合同项目实施期间，乙方人员调整的培训工作由乙方自\n行负责。\n（4）乙方在本合同项目执行中，对问题数据和错误数据要有补\n救和补偿措施。\n（5）乙方必须严格履行施工场地和施工期间的防疫、防火、防\n水、防盗、网络和信息安全，以及场地和设备的卫生保洁等主体责任，\n交易\n制定防疫、防火、防水、防盗、网络信息安全具体措施并报招标方备\n案。\n（6）乙方对其参加此次提供技术服务的人员的人身安全及其财\n\n信息等不被披露。一旦发现有上述保密信息泄露事件，双方应合作采\n取一切合理措施避免或者减轻损害后果的产生。\n第九条权利担保\n1.甲方保证提供给乙方的资料、信息内容合法，不侵犯第三方的\n合法权益。如因甲方原因致使乙方遭受第三方追诉的，甲方应承担由\n此给乙方造成的损失并承担违约责任。\n2.乙方保证在本服务实施过程中，不侵犯第三方的合法权益。如\n因乙方原因致使甲方遭受第三方追诉的，乙方应承担由此给甲方造成\n的损失并承担违约责任。\n第十条不可抗力\n1.合同双方中的任何一方，因战争、严重水灾、火灾、台风和地\n震等不可抗力因素而影响合同执行时，则延长履行合同的期限，相当\n于事故所影响的时间。\n2.发生事故一方应在事件发生5个工作日内将发生不可抗力事故\n的情况通知对方，并及时将有关证明文件提交给另一方确认。\n3.如不可抗力事故终止或被排除后，发生事故一方应尽快告知对\n方。\n4.如果不可抗力持续时间超过30天，双方将通过友好协商解决\n此后的合同执行问题。\n第十一条争议解决\n甲乙双方发生与本合同有关的一切争执，双方应通过协商解决，\n10\n\n如协商不成，则双方均可向甲方所在地人民法院提起诉讼。\n第十二条其他\n1.本合同签订后，如需对合同进行修改，可经双方协商一致并签\n订补充协议作为本合同附件来修改或补充合同内容。\n2.本合同一式陆份，甲乙双方各执参份，同具法律效力。\n皖云传\n甲方：安徽皖云传媒科技股有限公司乙方：成都索贝运维数码科技有限公司\n专用章\n开户行：中国光大银行成越光华支行\n13600008810\n斌翟\n徐冰\n法人或委托代理48322\n法人或委托代理火：\n印应\n（签字）\n（签字）\n3401040486323\n地址：\n地址：成都高新区天府二街138\n号3栋13层1315号\n交\n易见证章', 'completed', '2025-06-23 09:34:16', '2025-06-23 09:35:25');
INSERT INTO `document_files` VALUES (105, 396, '0_索贝支持文体直播马拉松报告_20250623T102427334Z.pdf', '索贝支持文体直播马拉松报告\\0_索贝支持文体直播马拉松报告_20250623T102427334Z.pdf', 'application/pdf', 3159044, 0, '项目名称：县级融媒体中心省级技\n术平台三期：皖云省级技术平台全\n徽\n媒体媒资库建设项目1标段合同\n项目名称：县级融媒体中心省级技术平台三期：皖云省\n级技术平台全媒体媒资库建设项目1标段\n项目编号：2022BTWCZ00498-1\n委托方：安徽皖云传媒科技股份有限公司\n（甲方）\n受托方：安徽长泰科技有限公司\n(乙方)\n签订时间：\n2022年9月\n签订地点：\n安徽省合肥市\n\n合同双方：\n委托方：安徽皖云传媒科技股份有限公司（以下简称“甲方”）\n受托方：安徽长泰科技有限公司（以下简称“乙方”）\n依据《中华人民共和国民法典》规定，甲乙双方就县级融媒体中\n心省级技术平台三期：皖云省级技术平台全媒体媒资库建设项目第1\n标段：内容采集、近线存储等设备事宜，经双方友好协商，签订本合\n同，以资共同遵守。甲乙双方在本合同项下所载各项条款表示完全同\n意和理解。\n第一条定义\n除非另有约定，本合同项下的相关词语、术语均以本条下列释译、\n表述为准。\n1.“本项目”指县级融媒体中心省级技术平台三期：皖云省级技\n术平台全媒体媒资库建设项目第1标段：内容采集、近线存储等设备。\n2.“合同总价款”：指甲方支付乙方按照合同约定完成全部项目\n的总款项。\n3.“合同执行期”：指甲乙双方在合同中约定，按总日历天数计\n算的有效完成合同任务的天数。\n4.“书面形式”：指合同书、信件和数据电文（包括电报、电传、\n传真、电子数据交换和电子邮件）等可以有形地表现所载内容的形式。\n5.“违约责任”：指合同一方不履行合同义务或履行合同义务不\n符合约定所应承担的责任。\n6.“索赔”：指在合同履行中，对于并非自己的过错，而是应由\n对方承担责任的情况造成的实际损失，向对方提出经济补偿和（或）\n工期顺延的要求。\n7.“不可抗力”：指不能预见、不能避免并不能克服的客观情况。\n8.本合同中规定按天计算时间的，开始当天不计入，从次日开始\n2\n\n计算。时限的最后一天是休息日或者其他法定节假日的，以节假日次\n日为时限的最后一天，但竣工日期除外。时限的最后一天的截止时间\n为当日24时。\n第二条项目标的技术内容、范围、形式和要求：\n1.产品明细\n序号\n货物名称\n品牌、型号规格\n单位\n数量\n单价\n总价\n、硬件部分：\n品牌：戴尔\n台\n4\n68000\n272000\n型号：戴尔T7920工作站\n软件部分：\n1、导入导出软件\n品牌：中科大洋\nSDI信号上载\n型号：XXSWP-CM-MediaI0\n工作站\n2、上下载审核软件\n套\n4\n50000\n200000\n品牌：中科大洋\n型号：XXSWP-CM-QC\n非编软件\n品牌：中科大洋\nA\n型号：D-Cube-Edit5\n一、硬件部分：\n品牌：戴尔\n54000\n台\n3\n18000\n型号：De11-T5820工作站\n二、软件部分：\n文件化上载\n导入导出软件\n2\n工作站\n品牌：中科大洋\n型号：XXSWP-CM-MediaIO\n套\n3\n20000\n60000\n上下载审核软件\n品牌：中科大洋\n型号：XXSWP-CM-QC\n品牌：康维讯\n高清监视器\n型号：KVM-2350W\n台\n9800\n3\n4\n39200\n企业版杀毒\n品牌：奇安信网神\n软件客户端\n套\n1\n20000\n20000\n型号：天擎终端安全管理系统V10\n授权\n品牌：松下\n套\n1\n472000\n472000\n蓝光盘库\n型号：LB-DH6\n品牌：松下\n个\n200\n2000\n400000\n\n型号：LM-BM60XB\n品牌：宁畅\n服务器\n台\n6\n2\n30000\n60000\n型号：R420G30\n品牌：长泰\n系统集成\n型号：定制\n套\n1\n90000\n90000\n<\n规格：定制\n合计\n1667200.00\n2.详细技术参数\n原产地及生\n序号\n货物名称\n详细的技术规格及配置\n产厂商\n一、硬件部分：\n品牌：戴尔\n型号：戴尔T7920工作站\n规格：\n1、CPU：IntelXeon4210R十核主频2.4G*2；内存：16G*2RECC\nDDR4；系统盘：512GBSSD